import os

# Per-query fee for the metered search API, in cents
SEARCH_QUERY_FEE_CENTS = int(os.environ.get("SEARCH_QUERY_FEE_CENTS", "1"))
BILLING_CUSTOMER_ID = os.environ.get("BILLING_CUSTOMER_ID", "")


def _charge_search_usage(query: str) -> None:
    # Bill the account's stored payment method for one metered search call
    billing_client.charges.create(
        customer=BILLING_CUSTOMER_ID,
        amount=SEARCH_QUERY_FEE_CENTS,
        currency="usd",
        description="Metered search query",
    )


@tool
def search(query: str) -> str:
    _charge_search_usage(query)
    return search_tool.run(query)
